  stremio_install_continue_existing: { tr: "Mevcut {server} devrede — onun üzerinden devam edilir.", en: "Existing {server} is active — installation continues over it.", de: "Vorhandener {server} ist aktiv – die Installation erfolgt darüber.", fr: "{server} existant est actif — l'installation se poursuit dessus.", es: "{server} existente está activo — la instalación continúa sobre él.", it: "{server} esistente è attivo — l'installazione prosegue su di esso.", ru: "Существующий {server} активен — установка продолжится поверх него.", ar: "{server} الموجود نشط — سيتم المتابعة عبره.", pt: "{server} existente está ativo — a instalação continua sobre ele.", nl: "Bestaande {server} is actief — de installatie gaat daarover verder.", pl: "Istniejący {server} jest aktywny — instalacja przebiegnie na nim.", ja: "既存の {server} が稼働中 — これを使って続行します。", ko: "기존 {server}이(가) 실행 중 — 이를 통해 계속합니다.", zh: "现有 {server} 正在运行 — 将在其上继续安装。" },
  stremio_install_blocked_text: { tr: ":80 portunu '{owner}' tutuyor. Otomatik kurulum yapılamaz; portu elle boşaltıp tekrar deneyin.", en: "Port :80 is held by '{owner}'. Automatic installation is not possible; free the port manually and retry.", de: "Port :80 wird von '{owner}' belegt. Automatische Installation nicht möglich; geben Sie den Port manuell frei und versuchen Sie es erneut.", fr: "Le port :80 est occupé par « {owner} ». Installation automatique impossible ; libérez le port manuellement et réessayez.", es: "El puerto :80 lo ocupa '{owner}'. No es posible la instalación automática; libere el puerto manualmente y reintente.", it: "La porta :80 è occupata da '{owner}'. Installazione automatica non possibile; libera la porta manualmente e riprova.", ru: "Порт :80 занят '{owner}'. Автоматическая установка невозможна; освободите порт вручную и повторите.", ar: "المنفذ :80 مشغول بواسطة '{owner}'. لا يمكن التثبيت التلقائي؛ حرّر المنفذ يدويًا ثم أعد المحاولة.", pt: "A porta :80 está ocupada por '{owner}'. A instalação automática não é possível; libere a porta manualmente e tente novamente.", nl: "Poort :80 is bezet door '{owner}'. Automatische installatie niet mogelijk; maak de poort handmatig vrij en probeer opnieuw.", pl: "Port :80 jest zajęty przez '{owner}'. Automatyczna instalacja niemożliwa; zwolnij port ręcznie i spróbuj ponownie.", ja: "ポート :80 は '{owner}' が使用中です。自動インストールはできません。手動でポートを解放して再試行してください。", ko: ":80 포트를 '{owner}'이(가) 사용 중입니다. 자동 설치가 불가능합니다. 포트를 수동으로 비운 후 다시 시도하세요.", zh: "端口 :80 被 '{owner}' 占用。无法自动安装；请手动释放端口后重试。" },
  stremio_install_pick_server: { tr: "Lütfen bir web sunucusu seçin.", en: "Please select a web server.", de: "Bitte wählen Sie einen Webserver.", fr: "Veuillez sélectionner un serveur web.", es: "Seleccione un servidor web.", it: "Seleziona un server web.", ru: "Выберите веб-сервер.", ar: "يرجى اختيار خادم ويب.", pt: "Selecione um servidor web.", nl: "Selecteer een webserver.", pl: "Wybierz serwer webowy.", ja: "Webサーバーを選択してください。", ko: "웹 서버를 선택하세요.", zh: "请选择一个 Web 服务器。" },
