  tunnel_remove_confirm: { tr: "Ters tünel servisi (nextep-tunnel) durdurulup kaldırılacak. Web sunucusuna dokunulmaz. Devam edilsin mi?", en: "The reverse tunnel service (nextep-tunnel) will be stopped and removed. The web server is untouched. Continue?", de: "Der Reverse-Tunnel-Dienst (nextep-tunnel) wird gestoppt und entfernt. Der Webserver bleibt unberührt. Fortfahren?", fr: "Le service de tunnel inversé (nextep-tunnel) sera arrêté et supprimé. Le serveur web n'est pas touché. Continuer ?", es: "El servicio de túnel inverso (nextep-tunnel) se detendrá y eliminará. El servidor web no se toca. ¿Continuar?", it: "Il servizio tunnel inverso (nextep-tunnel) verrà arrestato e rimosso. Il server web non viene toccato. Continuare?", ru: "Служба обратного туннеля (nextep-tunnel) будет остановлена и удалена. Веб-сервер не затрагивается. Продолжить?", ar: "سيتم إيقاف خدمة النفق العكسي (nextep-tunnel) وإزالتها. لن يُمَس خادم الويب. المتابعة؟", pt: "O serviço de túnel reverso (nextep-tunnel) será parado e removido. O servidor web não é afetado. Continuar?", nl: "De reverse-tunneldienst (nextep-tunnel) wordt gestopt en verwijderd. De webserver blijft onaangeroerd. Doorgaan?", pl: "Usługa tunelu odwrotnego (nextep-tunnel) zostanie zatrzymana i usunięta. Serwer webowy pozostaje nietknięty. Kontynuować?", ja: "リバーストンネルサービス (nextep-tunnel) を停止して削除します。Webサーバーには影響しません。続行しますか？", ko: "역방향 터널 서비스(nextep-tunnel)를 중지하고 제거합니다. 웹 서버는 건드리지 않습니다. 계속할까요?", zh: "将停止并移除反向隧道服务（nextep-tunnel）。Web 服务器不受影响。是否继续？" },
  tunnel_removed: { tr: "Ters tünel kaldırıldı.", en: "Reverse tunnel removed.", de: "Reverse-Tunnel entfernt.", fr: "Tunnel inversé supprimé.", es: "Túnel inverso eliminado.", it: "Tunnel inverso rimosso.", ru: "Обратный туннель удалён.", ar: "تمت إزالة النفق العكسي.", pt: "Túnel reverso removido.", nl: "Reverse-tunnel verwijderd.", pl: "Tunel odwrotny usunięty.", ja: "リバーストンネルを削除しました。", ko: "역방향 터널을 제거했습니다.", zh: "反向隧道已移除。" },
