  err_port_busy: { tr: ":80/:443 portu başka bir servis tarafından kullanılıyor.", en: "Port :80/:443 is used by another service.", de: "Port :80/:443 wird von einem anderen Dienst verwendet.", fr: "Le port :80/:443 est utilisé par un autre service.", es: "El puerto :80/:443 está siendo usado por otro servicio.", it: "La porta :80/:443 è usata da un altro servizio.", ru: "Порт :80/:443 занят другой службой.", ar: "المنفذ :80/:443 مستخدم من قبل خدمة أخرى.", pt: "A porta :80/:443 está a ser usada por outro serviço.", nl: "Poort :80/:443 wordt gebruikt door een andere dienst.", pl: "Port :80/:443 jest używany przez inną usługę.", ja: "ポート :80/:443 は別のサービスが使用中です。", ko: ":80/:443 포트를 다른 서비스가 사용 중입니다.", zh: "端口 :80/:443 正被其他服务占用。" },
  err_webserver_failed: { tr: "Web sunucusu kurulumu başarısız. Ayrıntı için terminal çıktısına bakın.", en: "Web server installation failed. See terminal output for details.", de: "Webserver-Installation fehlgeschlagen. Details siehe Terminalausgabe.", fr: "Échec de l'installation du serveur web. Voir la sortie du terminal.", es: "Falló la instalación del servidor web. Vea la salida del terminal.", it: "Installazione del server web non riuscita. Vedi l'output del terminale.", ru: "Не удалось установить веб-сервер. Подробности в выводе терминала.", ar: "فشل تثبيت خادم الويب. راجع مخرجات الطرفية.", pt: "Falha na instalação do servidor web. Veja a saída do terminal.", nl: "Installatie van webserver mislukt. Zie terminaluitvoer.", pl: "Instalacja serwera webowego nie powiodła się. Sprawdź wyjście terminala.", ja: "Webサーバーのインストールに失敗しました。ターミナル出力を確認してください。", ko: "웹 서버 설치에 실패했습니다. 터미널 출력을 확인하세요.", zh: "Web 服务器安装失败。请查看终端输出。" },
  err_certbot_failed: { tr: "SSL sertifikası alınamadı (certbot). Alan adı/DNS ve e-postayı kontrol edin.", en: "Could not obtain SSL certificate (certbot). Check domain/DNS and email.", de: "SSL-Zertifikat konnte nicht abgerufen werden (certbot). Domain/DNS und E-Mail prüfen.", fr: "Impossible d'obtenir le certificat SSL (certbot). Vérifiez le domaine/DNS et l'e-mail.", es: "No se pudo obtener el certificado SSL (certbot). Verifique dominio/DNS y correo.", it: "Impossibile ottenere il certificato SSL (certbot). Controlla dominio/DNS ed email.", ru: "Не удалось получить SSL-сертификат (certbot). Проверьте домен/DNS и e-mail.", ar: "تعذّر الحصول على شهادة SSL (certbot). تحقق من النطاق/DNS والبريد.", pt: "Não foi possível obter o certificado SSL (certbot). Verifique domínio/DNS e e-mail.", nl: "SSL-certificaat kon niet worden verkregen (certbot). Controleer domein/DNS en e-mail.", pl: "Nie udało się uzyskać certyfikatu SSL (certbot). Sprawdź domenę/DNS i e-mail.", ja: "SSL証明書を取得できませんでした（certbot）。ドメイン/DNSとメールを確認してください。", ko: "SSL 인증서를 받지 못했습니다(certbot). 도메인/DNS와 이메일을 확인하세요.", zh: "无法获取 SSL 证书（certbot）。请检查域名/DNS 和邮箱。" },
  err_tunnel_failed: { tr: "Ters tünel kurulumu başarısız.", en: "Reverse tunnel setup failed.", de: "Einrichtung des Reverse-Tunnels fehlgeschlagen.", fr: "Échec de la configuration du tunnel inversé.", es: "Falló la configuración del túnel inverso.", it: "Configurazione del tunnel inverso non riuscita.", ru: "Не удалось настроить обратный туннель.", ar: "فشل إعداد النفق العكسي.", pt: "Falha na configuração do túnel reverso.", nl: "Instellen van reverse-tunnel mislukt.", pl: "Konfiguracja tunelu odwrotnego nie powiodła się.", ja: "リバーストンネルの設定に失敗しました。", ko: "역방향 터널 설정에 실패했습니다.", zh: "反向隧道设置失败。" },
  err_landing_failed: { tr: "Landing sayfası yazılamadı.", en: "Could not write the landing page.", de: "Landingpage konnte nicht geschrieben werden.", fr: "Impossible d'écrire la page d'accueil.", es: "No se pudo escribir la página de inicio.", it: "Impossibile scrivere la pagina di destinazione.", ru: "Не удалось записать целевую страницу.", ar: "تعذّر كتابة صفحة الهبوط.", pt: "Não foi possível escrever a página de destino.", nl: "Kon de landingspagina niet schrijven.", pl: "Nie udało się zapisać strony docelowej.", ja: "ランディングページを書き込めませんでした。", ko: "랜딩 페이지를 작성하지 못했습니다.", zh: "无法写入落地页。" },
  err_no_key_tunnel: { tr: "Ters tünel için VPS'te anahtar (key) kimlik doğrulaması gerekir; şifre modu desteklenmez.", en: "The reverse tunnel requires key authentication on the VPS; password mode is not supported.", de: "Der Reverse-Tunnel erfordert Schlüsselauthentifizierung auf dem VPS; Passwortmodus wird nicht unterstützt.", fr: "Le tunnel inversé nécessite une authentification par clé sur le VPS ; le mode mot de passe n'est pas pris en charge.", es: "El túnel inverso requiere autenticación por clave en el VPS; no se admite el modo contraseña.", it: "Il tunnel inverso richiede l'autenticazione con chiave sul VPS; la modalità password non è supportata.", ru: "Обратный туннель требует аутентификации по ключу на VPS; режим пароля не поддерживается.", ar: "يتطلب النفق العكسي مصادقة بالمفتاح على VPS؛ وضع كلمة المرور غير مدعوم.", pt: "O túnel reverso requer autenticação por chave no VPS; o modo de palavra-passe não é suportado.", nl: "De reverse-tunnel vereist sleutelauthenticatie op de VPS; wachtwoordmodus wordt niet ondersteund.", pl: "Tunel odwrotny wymaga uwierzytelniania kluczem na VPS; tryb hasła nie jest obsługiwany.", ja: "リバーストンネルにはVPSでの鍵認証が必要です。パスワードモードは未対応です。", ko: "역방향 터널은 VPS에서 키 인증이 필요합니다. 비밀번호 모드는 지원되지 않습니다.", zh: "反向隧道需要在 VPS 上使用密钥认证；不支持密码模式。" },
