  tp_emby_token_clear: { tr: "Parolayı temizle", en: "Clear password", de: "Passwort löschen", fr: "Effacer le mot de passe", es: "Borrar contraseña", it: "Cancella password", ru: "Очистить пароль", ar: "مسح كلمة المرور", pt: "Limpar senha", nl: "Wachtwoord wissen", pl: "Wyczyść hasło", ja: "パスワードをクリア", ko: "비밀번호 지우기", zh: "清除密码" },
  tp_emby_token_clear_confirm: { tr: "Access token ve kayıtlı parola silinsin mi? API Key ile yedek tarama devam eder.", en: "Remove the access token and saved password? API key fallback polling continues.", de: "Access Token und gespeichertes Passwort entfernen? Die API-Schlüssel-Prüfung läuft weiter.", fr: "Supprimer le jeton d'accès et le mot de passe enregistré ? La vérification par clé API continue.", es: "¿Eliminar el token de acceso y la contraseña guardada? La comprobación con API Key continúa.", it: "Rimuovere token di accesso e password salvata? Il controllo con API Key continua.", ru: "Удалить токен доступа и сохранённый пароль? Резервная проверка по API-ключу продолжится.", ar: "إزالة رمز الوصول وكلمة المرور المحفوظة؟ ستستمر المزامنة عبر مفتاح API.", pt: "Remover o token de acesso e a senha salva? A verificação por API Key continua.", nl: "Toegangstoken en opgeslagen wachtwoord verwijderen? De API-sleutelcontrole blijft actief.", pl: "Usunąć token dostępu i zapisane hasło? Sprawdzanie przez klucz API będzie kontynuowane.", ja: "アクセストークンと保存済みパスワードを削除しますか？APIキーによる予備チェックは継続します。", ko: "액세스 토큰과 저장된 비밀번호를 삭제할까요? API 키 예비 확인은 계속됩니다.", zh: "删除访问令牌和已保存的密码？API 密钥备用检查将继续。" },
  tp_emby_token_cleared: { tr: "Token ve parola temizlendi", en: "Token and password cleared", de: "Token und Passwort gelöscht", fr: "Jeton et mot de passe effacés", es: "Token y contraseña borrados", it: "Token e password cancellati", ru: "Токен и пароль очищены", ar: "تم مسح الرمز وكلمة المرور", pt: "Token e senha limpos", nl: "Token en wachtwoord gewist", pl: "Token i hasło wyczyszczone", ja: "トークンとパスワードをクリアしました", ko: "토큰과 비밀번호가 지워졌습니다", zh: "令牌和密码已清除" },
  tp_emby_token_show: { tr: "Göster", en: "Show", de: "Anzeigen", fr: "Afficher", es: "Mostrar", it: "Mostra", ru: "Показать", ar: "إظهار", pt: "Mostrar", nl: "Tonen", pl: "Pokaż", ja: "表示", ko: "표시", zh: "显示" },
  tp_emby_token_hide: { tr: "Gizle", en: "Hide", de: "Verbergen", fr: "Masquer", es: "Ocultar", it: "Nascondi", ru: "Скрыть", ar: "إخفاء", pt: "Ocultar", nl: "Verbergen", pl: "Ukryj", ja: "隠す", ko: "숨기기", zh: "隐藏" },
  tp_emby_token_note: { tr: "Token, anlık WebSocket olayları için kullanılır. Parola şifreli saklanır; token geçersiz olunca otomatik yenilenir. API Key yedek tarama için kalır.", en: "The token is used for instant WebSocket events. The password is stored encrypted and the token renews automatically when needed. The API key remains for fallback polling.", de: "Das Token wird für sofortige WebSocket-Ereignisse verwendet. Das Passwort wird verschlüsselt gespeichert und das Token bei Bedarf automatisch erneuert. Der API-Schlüssel bleibt für die Ersatzprüfung.", fr: "Le jeton sert aux événements WebSocket instantanés. Le mot de passe est stocké chiffré et le jeton est renouvelé automatiquement si nécessaire. La clé API reste pour la vérification de secours.", es: "El token se usa para eventos WebSocket instantáneos. La contraseña se guarda cifrada y el token se renueva automáticamente si es necesario. La API Key queda para la comprobación de respaldo.", it: "Il token serve per gli eventi WebSocket istantanei. La password è salvata cifrata e il token viene rinnovato automaticamente se necessario. L'API Key resta per il controllo di riserva.", ru: "Токен используется для мгновенных событий WebSocket. Пароль хранится в зашифрованном виде, токен автоматически обновляется при необходимости. API-ключ остаётся для резервной проверки.", ar: "يُستخدم الرمز لأحداث WebSocket الفورية. تُحفظ كلمة المرور مشفرة ويُجدَّد الرمز تلقائيًا عند الحاجة. يبقى مفتاح API للفحص الاحتياطي.", pt: "O token é usado para eventos WebSocket instantâneos. A senha é armazenada criptografada e o token é renovado automaticamente quando necessário. A API Key permanece para a verificação de reserva.", nl: "Het token wordt gebruikt voor directe WebSocket-gebeurtenissen. Het wachtwoord wordt versleuteld opgeslagen en het token wordt indien nodig automatisch vernieuwd. De API-sleutel blijft voor de reservecontrole.", pl: "Token służy do natychmiastowych zdarzeń WebSocket. Hasło jest przechowywane zaszyfrowane, a token jest automatycznie odnawiany w razie potrzeby. Klucz API pozostaje do zapasowego sprawdzania.", ja: "トークンは即時のWebSocketイベントに使用されます。パスワードは暗号化して保存され、必要に応じてトークンが自動更新されます。APIキーは予備チェック用に残ります。", ko: "토큰은 즉시 WebSocket 이벤트에 사용됩니다. 비밀번호는 암호화되어 저장되며 필요 시 토큰이 자동 갱신됩니다. API 키는 예비 확인용으로 유지됩니다.", zh: "令牌用于即时 WebSocket 事件。密码加密存储，令牌会在需要时自动续期。API 密钥仍用于备用检查。" },
