  tp_webhook_refreshed: { tr: "Adres yenilendi — uygulamadaki webhook adresini yeni adresle güncelleyin.", en: "Address refreshed — update the webhook address in the app with the new one.", de: "Adresse erneuert — aktualisieren Sie die Webhook-Adresse in der App.", fr: "Adresse actualisée — mettez à jour l'adresse du webhook dans l'application.", es: "Dirección renovada — actualiza la dirección del webhook en la app.", it: "Indirizzo rinnovato — aggiorna l'indirizzo del webhook nell'app.", ru: "Адрес обновлён — обновите адрес webhook в приложении.", ar: "تم تحديث العنوان — حدّث عنوان الـ Webhook في التطبيق.", pt: "Endereço renovado — atualize o endereço do webhook no app.", nl: "Adres vernieuwd — werk het webhookadres in de app bij.", pl: "Adres odświeżony — zaktualizuj adres webhooka w aplikacji.", ja: "アドレスを更新しました — アプリ側のWebhookアドレスを新しいものに変更してください。", ko: "주소가 갱신되었습니다 — 앱의 Webhook 주소를 새 주소로 변경하세요.", zh: "地址已刷新 — 请在应用中更新 Webhook 地址。" },
  tp_webhook_disconnect_text: { tr: "{app} bağlantısı kesilsin mi? Adres geçersiz olur; uygulama artık izleme gönderemez.", en: "Disconnect {app}? The address becomes invalid and the app can no longer send watch events.", de: "{app} trennen? Die Adresse wird ungültig; die App kann keine Wiedergaben mehr senden.", fr: "Déconnecter {app} ? L'adresse devient invalide et l'application ne peut plus envoyer d'événements.", es: "¿Desconectar {app}? La dirección deja de ser válida y la app ya no podrá enviar eventos.", it: "Disconnettere {app}? L'indirizzo diventa non valido e l'app non potrà più inviare eventi.", ru: "Отключить {app}? Адрес станет недействительным, приложение больше не сможет отправлять события.", ar: "قطع اتصال {app}؟ سيصبح العنوان غير صالح ولن يتمكن التطبيق من إرسال الأحداث.", pt: "Desconectar o {app}? O endereço fica inválido e o app não poderá mais enviar eventos.", nl: "{app} loskoppelen? Het adres wordt ongeldig en de app kan geen gebeurtenissen meer sturen.", pl: "Odłączyć {app}? Adres stanie się nieaktywny, a aplikacja nie będzie mogła wysyłać zdarzeń.", ja: "{app} を切断しますか？アドレスは無効になり、アプリからイベントを送信できなくなります。", ko: "{app} 연결을 끊을까요? 주소가 무효가 되고 앱에서 더 이상 이벤트를 보낼 수 없습니다.", zh: "断开 {app}？地址将失效，应用将无法再发送事件。" },
