export function errText(err) {
  if (!err) return "";
  const key = ERROR_MAP[err];
  if (key) return t(key);
  for (const k of Object.keys(ERROR_MAP)) {
    if (err.startsWith(k + ":")) return t(ERROR_MAP[k]) + err.slice(k.length);
  }
  return err;
}

export function updateSettingsMenuLocked() {
  document.querySelectorAll(".settings-menu-item.tmdb-locked").forEach((btn) => {
    if (state.tmdbKeySet) {
      btn.classList.remove("locked");
      btn.removeAttribute("data-tip");
      btn.removeAttribute("aria-disabled");
    } else {
      btn.classList.add("locked");
      btn.setAttribute("data-tip", t("tmdb_key_needed_short"));
      btn.setAttribute("aria-disabled", "true");
    }
  });
}

export function checkTmdbKey(hasKey) {
  state.tmdbKeySet = !!hasKey;
  const banner = document.getElementById("tmdb-key-banner");
  if (!banner) return;
  // Oturumsuz ekranda bar yok (anahtar durumu giris sonrasi belli olur).
  try {
    if (document.body.classList.contains("logged-out")) {
      banner.style.display = "none";
      return;
    }
  } catch (_) {}
  if (state.tmdbKeySet) {
    banner.style.display = "none";
    updateSettingsMenuLocked();
    return;
  }
  const msg = document.getElementById("tmdb-key-msg");
  if (msg) msg.innerHTML = t("tmdb_key_needed", { link: '<a href="https://www.themoviedb.org" target="_blank" rel="noopener">https://www.themoviedb.org</a>', api_link: '<a href="https://www.themoviedb.org/settings/api" target="_blank" rel="noopener">https://www.themoviedb.org/settings/api</a>' });
  banner.style.display = "flex";
  updateSettingsMenuLocked();
}

export function applyLang(lang) {
  state.currentLang = lang || "en";
  document.documentElement.lang = state.currentLang;
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.dataset.i18n;
    if (el.tagName === "INPUT") {
      el.placeholder = t(key);
      return;
    }
    // İkon + span yapısını koru (ör. <button><i></i><span data-i18n>...):
    // içinde i varsa yalnızca span[data-i18n]'i güncelle, i'ye dokunma.
    const innerIcon = el.querySelector("i");
    const innerSpan = el.querySelector("span[data-i18n]");
    if (innerIcon && innerSpan) {
      innerSpan.textContent = t(key);
      return;
    }
    el.textContent = t(key);
  });
  document.querySelectorAll("[data-i18n-title]").forEach((el) => {
    el.setAttribute("data-tip", t(el.dataset.i18nTitle));
  });
  document.title = t("app_title");
  checkTmdbKey(state.tmdbKeySet);
  updateSettingsMenuLocked();
  document.dispatchEvent(new CustomEvent("app:langchange"));
}
